SELECT p.id, 'research', v.item_key, v.item_type, v.title,
       v.plain_meaning, v.display_order, v.everyday_example, v.contextual_use, v.expected_output,
       v.curriculum_anchors, v.claim_review_state, v.claim_evidence, v.claim_sources,
       v.learning_label, v.learning_url, v.learning_resource_type,
       v.learning_source_reference, v.learning_level, v.learning_duration,
       v.learning_access, v.learning_verified_on::date,
       'fixed_programme_guidance_not_selectable', v.limitations, TRUE, 'source_backed'
FROM skillup_dev.programmes p
CROSS JOIN (VALUES
('social_research_evidence_types', 'knowledge', 'Quantitative and qualitative evidence', 'Quantitative evidence is information shown as numbers, such as how many students use the library. Qualitative evidence is people''s words and explanations, such as why they go or stay away. Each shows a different part of the picture.', 10, 'A survey can show how many students use the library after class. Interviews can help explain why some stay and others leave. This is an example, not an assigned project.', 'Your Sociology programme teaches you to compare these ways of gathering information, decide what each can show, and notice what it may miss.', 'Compare what a small set of numbers can show with what people''s explanations add. Name one thing each cannot tell you. This is optional practice, not an assigned assessment.', '["SSC 302","SOC 301","SSC 401","SOC 408"]'::jsonb, 'approved', '{"claims":{"item_identity":["nuc_social_sciences_ccmas_2023:sociology_soc301_outcomes","openlearn_reading_evidence:Introduction"],"checkpoint_fit":["nuc_social_sciences_ccmas_2023:sociology_soc301_outcomes","nuc_social_sciences_ccmas_2023:sociology_ssc302","nuc_social_sciences_ccmas_2023:sociology_ssc401","nuc_social_sciences_ccmas_2023:sociology_soc408"],"plain_meaning":["openlearn_reading_evidence:Introduction"],"contextual_use":["nuc_social_sciences_ccmas_2023:sociology_soc301_outcomes"],"expected_output":["nuc_social_sciences_ccmas_2023:sociology_soc301_outcomes"]}}'::jsonb, '[{"id":"nuc_social_sciences_ccmas_2023","title":"Social Sciences CCMAS 2023","publisher":"National Universities Commission","url":"https://www.nuc.edu.ng/wp-content/uploads/2026/03/Social-Sciences-CCMAS-FINAL-2023-A.pdf","jurisdiction":"Nigeria","locators":{"sociology_soc301_outcomes":"Sociology programme, learning outcomes, printed p. 334","sociology_ssc302":"Research Method I, printed p. 333","sociology_ssc401":"Research Method II, printed p. 337","sociology_soc408":"Research Project, printed p. 338"}},{"id":"openlearn_reading_evidence","title":"Reading evidence","publisher":"The Open University, OpenLearn","url":"https://www.open.edu/openlearn/society-politics-law/sociology/reading-evidence/content-section-0?intro=1","jurisdiction":"International","locators":{"Introduction":"Introduction, social-science evidence types and interpretation"}}]'::jsonb, 'Explore how social scientists read numerical and textual evidence', 'https://www.open.edu/openlearn/society-politics-law/sociology/reading-evidence/content-section-0?intro=1', 'open_course', '{"id":"openlearn_reading_evidence","title":"Reading evidence","publisher":"The Open University, OpenLearn","url":"https://www.open.edu/openlearn/society-politics-law/sociology/reading-evidence/content-section-0?intro=1","jurisdiction":"International","locator":{"Introduction":"Introduction, social-science evidence types and interpretation","course_overview":"Course overview, quantitative and qualitative evidence","quantitative_and_qualitative_sections":"Course sections 1.2 Quantitative evidence and 1.3 Qualitative evidence"},"resource_facts":{"level":"Level 1: Introductory","estimated_duration":"12 hours","access":"Free course content; an account is needed for profile/progress and a statement of participation."}}'::jsonb, 'Level 1: Introductory', '12 hours', 'Free course content; an account is needed for profile/progress and a statement of participation.', '2026-10-08', '["This explanation does not claim that either evidence type is always superior or required for every study.","The linked course is optional learning support, not a Nigerian curriculum requirement."]'::jsonb),
('social_research_method_selection', 'method', 'Choose a research method for a question', 'A research method is a planned way to answer a question. A survey can show how common something is; interviews can help explain people''s experiences.', 20, 'If your class wants to understand lateness, a survey can show how often students arrive late. Interviews can help explain the reasons. These are examples, not assigned research.', 'Your Sociology programme teaches different ways to collect information, when each may help, and why a researcher should explain the choice.', 'Write down a question, the information you would need, one way to collect it, and one reason that choice may work. This is optional practice, not an assigned assessment.', '["SSC 302","SOC 301","SSC 401","SOC 408"]'::jsonb, 'approved', '{"claims":{"item_identity":["nuc_social_sciences_ccmas_2023:sociology_soc301_contents","openlearn_research_methodology:research_questions_and_methods"],"checkpoint_fit":["nuc_social_sciences_ccmas_2023:sociology_ssc302","nuc_social_sciences_ccmas_2023:sociology_soc301_outcomes","nuc_social_sciences_ccmas_2023:sociology_soc301_contents"],"plain_meaning":["openlearn_research_methodology:research_questions_and_methods"],"contextual_use":["nuc_social_sciences_ccmas_2023:sociology_soc301_contents"],"expected_output":["nuc_social_sciences_ccmas_2023:sociology_soc301_outcomes"]}}'::jsonb, '[{"id":"nuc_social_sciences_ccmas_2023","title":"Social Sciences CCMAS 2023","publisher":"National Universities Commission","url":"https://www.nuc.edu.ng/wp-content/uploads/2026/03/Social-Sciences-CCMAS-FINAL-2023-A.pdf","jurisdiction":"Nigeria","locators":{"sociology_soc301_contents":"Sociology programme, course contents, printed p. 335","sociology_ssc302":"Research Method I, printed p. 333","sociology_soc301_outcomes":"Sociology programme, learning outcomes, printed p. 334"}},{"id":"openlearn_research_methodology","title":"Defining your research methodology","publisher":"The Open University, OpenLearn","url":"https://www.open.edu/openlearn/course/view.php?id=18286","jurisdiction":"International","locators":{"research_questions_and_methods":"Sections on research questions, methodological approaches and selecting methodology"}}]'::jsonb, 'Compare research questions, methods and data choices', 'https://www.open.edu/openlearn/course/view.php?id=18286', 'learning_article', '{"id":"openlearn_research_methodology","title":"Defining your research methodology","publisher":"The Open University, OpenLearn","url":"https://www.open.edu/openlearn/course/view.php?id=18286","jurisdiction":"International","locator":{"research_questions_and_methods":"Sections on research questions, methodological approaches and selecting methodology","data_collection_and_analysis":"Sections on data collection techniques and data analysis"},"resource_facts":{"level":"Not stated by publisher","estimated_duration":"Not stated by publisher","access":"Openly readable online; no course credential is claimed for this article."}}'::jsonb, 'Not stated by publisher', 'Not stated by publisher', 'Openly readable online; no course credential is claimed for this article.', '2026-10-08', '["The source does not establish a fixed universal sequence or a single required method for every Sociology learner.","The linked page is an article and is not described as a course or credential."]'::jsonb),
('ethical_social_research', 'competency', 'Treat people fairly in research', 'Research ethics means treating people fairly and carefully when you ask them for information, and handling their answers honestly.', 30, 'If you ask classmates about a difficult topic, explain why you are asking, let them choose whether to answer, and keep their replies private. This is a learning example, not permission to conduct a real study.', 'Your Sociology programme teaches you to treat people fairly during research, handle information honestly, and avoid claiming more than the information can support.', 'Make a short checklist: explain the question, let people choose whether to answer, protect their information, and be careful about what you conclude. This is practice, not approval to conduct research.', '["SOC 301","SSC 401","SOC 408"]'::jsonb, 'approved', '{"claims":{"item_identity":["nuc_social_sciences_ccmas_2023:sociology_soc301_outcomes","openlearn_ethical_researcher:course_description_and_learning_outcomes"],"checkpoint_fit":["nuc_social_sciences_ccmas_2023:sociology_soc301_outcomes","nuc_social_sciences_ccmas_2023:sociology_soc301_contents"],"plain_meaning":["nuc_social_sciences_ccmas_2023:sociology_soc301_outcomes","openlearn_ethical_researcher:course_description_and_learning_outcomes"],"contextual_use":["nuc_social_sciences_ccmas_2023:sociology_soc301_outcomes","openlearn_ethical_researcher:course_description_and_learning_outcomes"],"expected_output":["nuc_social_sciences_ccmas_2023:sociology_soc301_outcomes"]}}'::jsonb, '[{"id":"nuc_social_sciences_ccmas_2023","title":"Social Sciences CCMAS 2023","publisher":"National Universities Commission","url":"https://www.nuc.edu.ng/wp-content/uploads/2026/03/Social-Sciences-CCMAS-FINAL-2023-A.pdf","jurisdiction":"Nigeria","locators":{"sociology_soc301_outcomes":"Sociology programme, learning outcomes, printed p. 334","sociology_soc301_contents":"Sociology programme, course contents, printed p. 335"}},{"id":"openlearn_ethical_researcher","title":"Becoming an ethical researcher","publisher":"The Open University, OpenLearn","url":"https://www.open.edu/openlearn/education-development/becoming-ethical-researcher","jurisdiction":"International","locators":{"course_description_and_learning_outcomes":"Course description and learning outcomes for planning, conducting and reporting research involving human participants"}}]'::jsonb, 'Work through ethical decisions in research with people', 'https://www.open.edu/openlearn/education-development/becoming-ethical-researcher', 'open_course', '{"id":"openlearn_ethical_researcher","title":"Becoming an ethical researcher","publisher":"The Open University, OpenLearn","url":"https://www.open.edu/openlearn/education-development/becoming-ethical-researcher","jurisdiction":"International","locator":{"course_description_and_learning_outcomes":"Course description and learning outcomes for planning, conducting and reporting research involving human participants","respect_and_consent_sessions":"Course content, sessions on showing respect and consent in research"},"resource_facts":{"level":"Level 3: Advanced","estimated_duration":"18 hours","access":"Free course content can be started without signing up; sign-up enables quizzes, activities, progress tracking and a free statement of participation.","credential_limit":"The Open University states its digital badge is not an OU-accredited qualification."}}'::jsonb, 'Level 3: Advanced', '18 hours', 'Free course content can be started without signing up; sign-up enables quizzes, activities, progress tracking and a free statement of participation.', '2026-10-08', '["The course is labelled Level 3: Advanced by OpenLearn; show it as optional further study, not as an entry prerequisite.","Its badge is not an Open University-accredited qualification.","Institutional ethics-review and applicable Nigerian requirements remain separate from this learning resource."]'::jsonb)
) AS v(item_key, item_type, title, plain_meaning, display_order, everyday_example,
       contextual_use, expected_output, curriculum_anchors, claim_review_state,
       claim_evidence, claim_sources, learning_label, learning_url,
       learning_resource_type, learning_source_reference, learning_level,
       learning_duration, learning_access, learning_verified_on, limitations)
WHERE lower(p.name) = lower('Sociology')
